mapper.select:
SELECT id, run_id, seq, event_type, payload_json::text AS payload_json, dedupe_key, created_at
FROM alphafrog_agent_run_event
WHERE run_id = #{runId}
  AND event_type = #{eventType}
ORDER BY seq ASC
LIMIT 1

SELECT e.id, e.run_id, e.seq, e.event_type, e.payload_json::text AS payload_json,
       e.dedupe_key, e.created_at
FROM alphafrog_agent_run_event e
JOIN alphafrog_agent_run r ON r.id = e.run_id
WHERE e.event_type = 'RUN_RECEIVED'
  AND e.created_at > #{createdSince}
  AND r.deployment_id = #{deploymentId}
  AND r.deployment_generation_id = #{deploymentGenerationId}
ORDER BY e.created_at DESC, e.id DESC
LIMIT #{limit}

SELECT e.id, e.run_id, e.seq, e.event_type, e.payload_json::text AS payload_json,
       e.dedupe_key, e.created_at
FROM alphafrog_agent_run_event e
JOIN alphafrog_agent_run r ON r.id = e.run_id
WHERE e.event_type = 'RUN_RECEIVED'
  AND e.created_at > #{createdSince}
  AND (e.created_at, e.id) > (#{cursorCreatedAt}, #{cursorId})
  AND r.deployment_id = #{deploymentId}
  AND r.deployment_generation_id = #{deploymentGenerationId}
ORDER BY e.created_at ASC, e.id ASC
LIMIT #{limit}

SELECT COALESCE(MAX(seq), 0)
FROM alphafrog_agent_run_event
WHERE run_id = #{runId}

SELECT DISTINCT run_id FROM alphafrog_agent_run_event WHERE run_id IN
#{runId}
AND ( (event_type = 'TOOL_CALL_STARTED' AND COALESCE(payload_json ->> 'tool_name', payload_json ->> 'toolName') = 'executePython') OR (event_type = 'PARALLEL_TASK_STARTED' AND payload_json ->> 'tool' = 'executePython') )
